  const tile = (w, h, inner, tr = "") => { const id = nid("wt"); return [id, `<defs><pattern id="${id}" patternUnits="userSpaceOnUse" width="${w}" height="${h}"${tr ? ` patternTransform="${tr}"` : ""}>${inner}</pattern></defs>`]; };
