    flowers: (w1, w2, top) => { const [id, d] = tile(56, 48, `<ellipse cx="26" cy="20" rx="4.4" ry="2" fill="${w2}" transform="rotate(-30 26 20)"/><ellipse cx="50" cy="12" rx="4" ry="1.8" fill="${w2}" transform="rotate(40 50 12)"/>${blossom(14, 14, 3.6, "#FFFFFF", "#F2C063")}${blossom(42, 36, 3.4, "#F7B6C8", "#FFD25E")}<circle cx="38" cy="8" r="1.4" fill="#fff" opacity=".8"/><circle cx="8" cy="38" r="1.2" fill="#F7B6C8" opacity=".8"/>`); return d + fillTile(id, top); },
